create or replace function public.set_driver_availability(p_status public.driver_availability) returns public.drivers language plpgsql security definer set search_path=public as $$ declare v_driver public.drivers; begin update drivers set availability_status=p_status,availability_updated_at=now(),updated_at=now() where id=current_driver_id() and account_status='active' returning * into v_driver; if not found then raise exception 'not_authorized'; end if; return v_driver; end $$;
create or replace function public.transition_booking(p_booking_id uuid,p_status public.booking_status) returns public.bookings language plpgsql security definer set search_path=public as $$ declare b public.bookings; begin select * into b from bookings where id=p_booking_id and assigned_driver_id=current_driver_id() for update;if not found then raise exception 'not_authorized';end if;if not ((b.status='accepted' and p_status='driver_en_route') or (b.status='driver_en_route' and p_status='driver_arrived') or (b.status='driver_arrived' and p_status='in_progress') or (b.status='in_progress' and p_status='completed')) then raise exception 'invalid_transition';end if;update bookings set status=p_status,driver_en_route_at=case when p_status='driver_en_route' then now() else driver_en_route_at end,driver_arrived_at=case when p_status='driver_arrived' then now() else driver_arrived_at end,started_at=case when p_status='in_progress' then now() else started_at end,completed_at=case when p_status='completed' then now() else completed_at end,updated_at=now() where id=p_booking_id returning * into b;if p_status='in_progress' then update drivers set availability_status='busy',availability_updated_at=now() where id=b.assigned_driver_id;end if;insert into booking_events(booking_id,event_type,actor_profile_id,actor_type) values(b.id,p_status::text,auth.uid(),'driver');return b;end $$;
create or replace function public.cancel_driver_booking(p_booking_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$ declare b public.bookings;begin if p_reason not in ('avería','emergencia','error','no puedo realizarlo','cliente no localizado','otro') then raise exception 'invalid_reason';end if;select * into b from bookings where id=p_booking_id and assigned_driver_id=current_driver_id() and status not in ('in_progress','completed','cancelled') for update;if not found then raise exception 'not_allowed';end if;update bookings set assigned_driver_id=null,status='dispatching',cancellation_reason=p_reason,dispatch_attempt=0,updated_at=now() where id=b.id;insert into booking_events(booking_id,event_type,actor_profile_id,actor_type,metadata) values(b.id,'driver_cancelled_redispatch',auth.uid(),'driver',jsonb_build_object('reason',p_reason));end $$;
create or replace function public.admin_assign_booking(p_booking_id uuid,p_driver_id uuid) returns public.bookings language plpgsql security definer set search_path=public as $$ declare b public.bookings;begin if not is_admin() then raise exception 'not_authorized';end if;select * into b from bookings where id=p_booking_id and status not in ('in_progress','completed','cancelled') for update;if not found then raise exception 'not_assignable';end if;update bookings set assigned_driver_id=p_driver_id,status='accepted',accepted_at=coalesce(accepted_at,now()),assigned_manually=true,assigned_by_admin=auth.uid(),updated_at=now() where id=p_booking_id returning * into b;update booking_offers set status='cancelled',responded_at=now() where booking_id=p_booking_id and status='pending';insert into booking_events(booking_id,event_type,actor_profile_id,actor_type,metadata) values(b.id,'admin_assigned',auth.uid(),'admin',jsonb_build_object('driver_id',p_driver_id));insert into audit_logs(actor_profile_id,action,entity,entity_id,metadata) values(auth.uid(),'booking.manual_assign','booking',b.id::text,jsonb_build_object('driver_id',p_driver_id));return b;end $$;
create policy profiles_admin_write on public.profiles for all using(is_admin()) with check(is_admin());
grant execute on function public.set_driver_availability(public.driver_availability),public.transition_booking(uuid,public.booking_status),public.cancel_driver_booking(uuid,text),public.admin_assign_booking(uuid,uuid) to authenticated;
